// Des: Tests page reading and human input on fake site
// Flo: find by role + label > scroll > click through real mouse events > type incl. Vietnamese > assert the site saw it
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-huma-inpu-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const inpu = @import("ru-huma-inpu.zig"); const conf = @import("cf-conf-load.zig");
const pace = @import("ru-huma-pace.zig"); const defc: conf.Conf = .{};
test "find by role and label, then click and type a post incl. Vietnamese" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/"); const open = (try rig.page.axFind(aren, "button", defc.labl_post_open, 0)) orelse return error.TestUnexpectedResult; try rig.page.scrollInto(aren, open); var env = rig.env(); const pnt = try rig.page.center(aren, open); try inpu.click(&env, pnt.x, pnt.y); const box = (try rig.page.axFind(aren, "textbox", defc.labl_post_boxz, 0)) orelse return error.TestUnexpectedResult; const bpt = try rig.page.center(aren, box); try inpu.click(&env, bpt.x, bpt.y); try inpu.typeText(&env, "Hello xin chào, bán xe đạp"); const pbt = (try rig.page.axFind(aren, "button", defc.labl_post_subm, 0)) orelse return error.TestUnexpectedResult; const ppt = try rig.page.center(aren, pbt); try inpu.click(&env, ppt.x, ppt.y); const rec = rig.waitRec("post", 5000) orelse return error.TestUnexpectedResult; try std.testing.expectEqualStrings("Hello xin chào, bán xe đạp", rec); try std.testing.expectEqual(@as(usize, 1), rig.mock.recNum("post")); }
test "label match ignores case and Vietnamese capitals; unknown label gives null" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/groups/77/"); try std.testing.expect((try rig.page.axFind(aren, "button", &.{"JOIN GROUP"}, 0)) != null); try std.testing.expect((try rig.page.axFind(aren, "button", &.{"khong co nut nay"}, 0)) == null); try std.testing.expectEqual(@as(usize, 1), try rig.page.axCount(aren, "button", &.{"join group"})); }
test "nth match picks the second reply button" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/notifications"); try std.testing.expectEqual(@as(usize, 2), try rig.page.axCount(aren, "button", defc.labl_repl_btnz)); const one = (try rig.page.axFind(aren, "button", defc.labl_repl_btnz, 0)).?; const two = (try rig.page.axFind(aren, "button", defc.labl_repl_btnz, 1)).?; try std.testing.expect(one != two); try std.testing.expect((try rig.page.axFind(aren, "button", defc.labl_repl_btnz, 2)) == null); }
test "key Enter sends the typed message" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/messages/t/42"); const box = (try rig.page.axFind(aren, "textbox", defc.labl_dmsg_boxz, 0)) orelse return error.TestUnexpectedResult; var env = rig.env(); const pnt = try rig.page.center(aren, box); try inpu.click(&env, pnt.x, pnt.y); try inpu.typeText(&env, "hi there"); try inpu.pressKey(&env, "Enter"); const rec = rig.waitRec("dm", 5000) orelse return error.TestUnexpectedResult; try std.testing.expectEqualStrings("hi there", rec); }
test "mouse path ends on the target and scrolling moves the page" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/"); var env = rig.env(); try inpu.moveTo(&env, 120.0, 80.0); try std.testing.expectEqual(@as(f64, 120.0), rig.page.mx); try std.testing.expectEqual(@as(f64, 80.0), rig.page.my); _ = try rig.page.evalVal(aren, "document.body.style.height='4000px'"); try inpu.scrollBy(&env, 300.0); const ys = rig.page.evalNum(aren, "Math.round(window.scrollY)"); try std.testing.expect(ys > 0); }
test "plan: ends exactly on the target, bends, and speeds up then slows down" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); var rng = pace.Rng.init(21); const pts = try inpu.plan(allo, &rng, 10.0, 10.0, 610.0, 330.0, 54); try std.testing.expect(pts.len >= 8); try std.testing.expectEqual(@as(f64, 610.0), pts[pts.len - 1].x); try std.testing.expectEqual(@as(f64, 330.0), pts[pts.len - 1].y); var maxd: f64 = 0; for (pts) |pnt| { const dev = @abs((pnt.x - 10.0) * 320.0 - (pnt.y - 10.0) * 600.0) / @sqrt(600.0 * 600.0 + 320.0 * 320.0); maxd = @max(maxd, dev); } try std.testing.expect(maxd > 0.5); var steps = try allo.alloc(f64, pts.len); var prx: f64 = 10.0; var pry: f64 = 10.0; var peak: f64 = 0; for (pts, 0..) |pnt, idx| { steps[idx] = @sqrt((pnt.x - prx) * (pnt.x - prx) + (pnt.y - pry) * (pnt.y - pry)); peak = @max(peak, steps[idx]); prx = pnt.x; pry = pnt.y; } try std.testing.expect(steps[0] < peak * 0.5); try std.testing.expect(steps[steps.len - 1] < peak * 0.5); }
test "plan: two plans between the same points are never the same path; a longer move takes more steps" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); var rng = pace.Rng.init(5); const one = try inpu.plan(allo, &rng, 0, 0, 400, 100, 90); const two = try inpu.plan(allo, &rng, 0, 0, 400, 100, 90); var same = true; for (one, 0..) |pnt, idx| { if (idx < two.len and (pnt.x != two[idx].x or pnt.y != two[idx].y) and idx + 1 < one.len) same = false; } try std.testing.expect(!same); const near = try inpu.plan(allo, &rng, 0, 0, 40, 10, 90); const far = try inpu.plan(allo, &rng, 0, 0, 1400, 700, 90); try std.testing.expect(far.len > near.len); const same_pt = try inpu.plan(allo, &rng, 5, 5, 5, 5, 90); try std.testing.expectEqual(@as(usize, 1), same_pt.len); }
test "common digraphs are found in either case; others are not" { try std.testing.expect(inpu.common('t', 'h')); try std.testing.expect(inpu.common('T', 'H')); try std.testing.expect(!inpu.common('q', 'z')); }
test "click lands near but not always on the center and sends move, down, up, click in order" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/"); var env = rig.env(); _ = try rig.page.evalVal(aren, "window.__ev=[];['pointermove','pointerdown','pointerup','click'].forEach(function(n){document.addEventListener(n,function(e){__ev.push([n,e.clientX,e.clientY,e.isTrusted])},true)})"); var idx: u32 = 0; while (idx < 6) : (idx += 1) { try inpu.click(&env, 200.0, 150.0); } const raw = try rig.page.evalStr(aren, "JSON.stringify(__ev)"); const doc = try std.json.parseFromSliceLeaky(std.json.Value, aren, raw, .{}); var downs: usize = 0; var offs: usize = 0; var xoff: usize = 0; var order_ok = true; var last: []const u8 = ""; for (doc.array.items) |row| { const nam = row.array.items[0].string; try std.testing.expect(row.array.items[3].bool); if (std.mem.eql(u8, nam, "pointerdown")) { downs += 1; const xpos = switch (row.array.items[1]) { .integer => |n| @as(f64, @floatFromInt(n)), .float => |n| n, else => 0 }; const ypos = switch (row.array.items[2]) { .integer => |n| @as(f64, @floatFromInt(n)), .float => |n| n, else => 0 }; try std.testing.expect(@abs(xpos - 200.0) <= 3.6 and @abs(ypos - 150.0) <= 3.6); if (xpos != 200.0 or ypos != 150.0) offs += 1; if (xpos != 200.0) xoff += 1; if (!std.mem.eql(u8, last, "pointermove")) order_ok = false; } if (std.mem.eql(u8, nam, "click") and !std.mem.eql(u8, last, "pointerup")) order_ok = false; last = nam; } try std.testing.expectEqual(@as(usize, 6), downs); try std.testing.expect(offs >= 3); try std.testing.expect(xoff >= 3); try std.testing.expect(order_ok); }
test "typing keeps the text exact, rolls some keys over, and long text is pasted whole" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/"); var env = rig.env(); _ = try rig.page.evalVal(aren, "window.__k=[];['keydown','keyup'].forEach(function(n){document.addEventListener(n,function(e){__k.push(n==='keydown'?'d':'u')},true)})"); const text = "the other thing in the garden is a rather nice red bike that nobody wants to ride in the rain, so then we sold it"; try inpu.typeText(&env, text); const raw = try rig.page.evalStr(aren, "__k.join('')"); try std.testing.expectEqual(text.len, std.mem.count(u8, raw, "d")); try std.testing.expectEqual(text.len, std.mem.count(u8, raw, "u")); try std.testing.expect(std.mem.find(u8, raw, "dd") != null); try std.testing.expect(std.mem.count(u8, raw, "dd") * 100 < text.len * 40); var long: [300]u8 = undefined; @memset(&long, 'a'); _ = try rig.page.evalVal(aren, "window.__k=[]"); try inpu.typeText(&env, &long); try std.testing.expectEqualStrings("", try rig.page.evalStr(aren, "__k.join('')")); }
test "scroll plan: decaying flicks, never below the distance, different each time" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); var rng = pace.Rng.init(8); const one = try inpu.flickPlan(allo, &rng, 1500.0); var sum: f64 = 0; var shrink: usize = 0; for (one, 0..) |val, idx| { sum += val; if (idx > 0 and val < one[idx - 1]) shrink += 1; } try std.testing.expect(sum >= 1500.0); try std.testing.expect(shrink * 3 >= one.len * 2); const two = try inpu.flickPlan(allo, &rng, 1500.0); try std.testing.expect(one.len != two.len or one[0] != two[0]); const up = try inpu.flickPlan(allo, &rng, -300.0); for (up) |val| try std.testing.expect(val < 0); }
test "scrolling reaches the asked distance on a real page" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/"); var env = rig.env(); _ = try rig.page.evalVal(aren, "document.body.style.height='9000px'"); try inpu.scrollBy(&env, 800.0); const ys = rig.page.evalNum(aren, "Math.round(window.scrollY)"); try std.testing.expect(ys >= 700); }
